  tools.exec_command({cmd:"rg -n \"struct DirtCourse|enum DirtCourse|struct InfieldLayout|enum InfieldLayout|fenceOffset|tentOrigins|func projection|audio-smoke|AudioSmoke\" Sources ../../docs/race-audio.md","max_output_tokens":8000})
