    enum Kind:Int { case market,workshop,cantina }
    let position:SIMD2<Double>,kind:Kind
    var activity:Double=1
    var infieldRepair=false
}

/// Fixed, predecoded voice budget. No file I/O or synthesis on the gameplay thread.
