            let audio=try RaceAudio(resources:Bundle.main.resourceURL!,offline:true)
            defer { audio.stop() }
            let format=audio.engine.manualRenderingFormat
            let buffer=AVAudioPCMBuffer(pcmFormat:format,frameCapacity:800)!
